/* System initialize for referenced model: 'MotMapped' */
void MotMapped_Init(X_MotMapped_n_T *localX)
{
  /* InitializeConditions for Integrator: '<S7>/Integrator' */
  localX->Integrator_CSTATE = MotMapped_P.Integrator_IC;
}

/* System reset for referenced model: 'MotMapped' */
void MotMapped_Reset(X_MotMapped_n_T *localX)
{
  /* InitializeConditions for Integrator: '<S7>/Integrator' */
  localX->Integrator_CSTATE = MotMapped_P.Integrator_IC;
}

/* Outputs for referenced model: 'MotMapped' */
void MotMapped(RT_MODEL_MotMapped_T * const MotMapped_M, const real_T
               *rtu_MotTrqCmd, const real_T *rtu_MotSpd, const real_T
               *rtu_BusVolt, real_T *rty_MotTrq, real_T *rty_MotCurnt,
               B_MotMapped_c_T *localB, X_MotMapped_n_T *localX)
{
  real_T u1;
  real_T u2;

  /* Lookup_n-D: '<S7>/Max Torque Limit' */
  localB->MaxTorqueLimit = look1_binlcapw(*rtu_MotSpd,
    MotMapped_P.MaxTorqueLimit_bp01Data, MotMapped_P.MaxTorqueLimit_tableData,
    64U);

  /* Integrator: '<S7>/Integrator' */
  localB->Integrator = localX->Integrator_CSTATE;

  /* Gain: '<S7>/Gain1' */
  u1 = 1.0 / MotMapped_P.Tc;
  localB->Gain1 = u1 * localB->Integrator;

  /* Product: '<S7>/Product' */
  localB->Product = 1.0 / localB->MaxTorqueLimit * localB->Gain1;

  /* Lookup_n-D: '<S7>/Interpolated zero-crossing' */
  localB->Interpolatedzerocrossing = look1_binlcpw(localB->Product,
    MotMapped_P.Interpolatedzerocrossing_bp01Data,
    MotMapped_P.Interpolatedzerocrossing_tableData, 1U);

  /* Product: '<S7>/Divide2' */
  *rty_MotTrq = localB->MaxTorqueLimit * localB->Interpolatedzerocrossing;

  /* Product: '<S6>/Product' */
  localB->Product_p = *rtu_MotSpd * *rty_MotTrq;

  /* Lookup_n-D: '<S6>/2-D Lookup Table' */
  localB->uDLookupTable = look2_binlcapw(*rtu_MotSpd, *rty_MotTrq,
    MotMapped_P.uDLookupTable_bp01Data, MotMapped_P.uDLookupTable_bp02Data,
    MotMapped_P.uDLookupTable_tableData, MotMapped_P.uDLookupTable_maxIndex, 86U);

  /* Sum: '<S4>/Add' */
  localB->Add = localB->Product_p + localB->uDLookupTable;

  /* Saturate: '<S4>/Saturation' */
  u1 = MotMapped_P.Saturation_LowerSat;
  u2 = MotMapped_P.Saturation_UpperSat;
  if (*rtu_BusVolt > u2) {
    localB->Saturation = u2;
  } else if (*rtu_BusVolt < u1) {
    localB->Saturation = u1;
  } else {
    localB->Saturation = *rtu_BusVolt;
  }

  /* End of Saturate: '<S4>/Saturation' */

  /* Product: '<S4>/Divide' */
  *rty_MotCurnt = localB->Add / localB->Saturation;

  /* Sum: '<S5>/Add' */
  localB->Add_l = localB->Product_p + localB->uDLookupTable;

  /* Gain: '<S5>/Gain' */
  localB->Gain = MotMapped_P.Gain_Gain * localB->Product_p;
  if (rtmIsMajorTimeStep(MotMapped_M)) {
    /* Gain: '<S5>/Gain1' incorporates:
     *  Constant: '<S3>/Constant'
     */
    localB->Gain1_n = MotMapped_P.Gain1_Gain * MotMapped_P.Constant_Value;
  }

  /* Sum: '<S5>/Subtract' */
  localB->Subtract = (localB->Gain1_n - localB->Gain) - localB->Add_l;

  /* Sum: '<S7>/Sum' */
  localB->Sum = *rtu_MotTrqCmd - localB->Gain1;
}

/* Update for referenced model: 'MotMapped' */
void MotMapped_Update(void)
{
}

/* Derivatives for referenced model: 'MotMapped' */
void MotMapped_Deriv(B_MotMapped_c_T *localB, XDot_MotMapped_n_T *localXdot)
{
  /* Derivatives for Integrator: '<S7>/Integrator' */
  localXdot->Integrator_CSTATE = localB->Sum;
}

/* Model initialize function */
void MotMapped_initialize(const char_T **rt_errorStatus, boolean_T
  *rt_stopRequested, RTWSolverInfo *rt_solverInfo, RT_MODEL_MotMapped_T *const
  MotMapped_M, B_MotMapped_c_T *localB, X_MotMapped_n_T *localX,
  rtwCAPI_ModelMappingInfo *rt_ParentMMI, const char_T *rt_ChildPath, int_T
  rt_ChildMMIIdx, int_T rt_CSTATEIdx)
{
  /* Registration code */

  /* initialize non-finites */
  rt_InitInfAndNaN(sizeof(real_T));

  /* non-finite (run-time) assignments */
  MotMapped_P.Saturation_UpperSat = rtInf;

  /* initialize real-time model */
  (void) memset((void *)MotMapped_M, 0,
                sizeof(RT_MODEL_MotMapped_T));

  /* initialize error status */
  rtmSetErrorStatusPointer(MotMapped_M, rt_errorStatus);

  /* initialize stop requested flag */
  rtmSetStopRequestedPtr(MotMapped_M, rt_stopRequested);

  /* initialize RTWSolverInfo */
  MotMapped_M->solverInfo = (rt_solverInfo);

  /* Set the Timing fields to the appropriate data in the RTWSolverInfo */
  rtmSetSimTimeStepPointer(MotMapped_M, rtsiGetSimTimeStepPtr
    (MotMapped_M->solverInfo));
  MotMapped_M->Timing.stepSize0 = (rtsiGetStepSize(MotMapped_M->solverInfo));

  /* block I/O */
  (void) memset(((void *) localB), 0,
                sizeof(B_MotMapped_c_T));

  /* Initialize DataMapInfo substructure containing ModelMap for C API */
  {
    MotMapped_InitializeDataMapInfo(MotMapped_M, localB, localX);
  }

  /* Initialize Parent model MMI */
  if ((rt_ParentMMI != (NULL)) && (rt_ChildPath != (NULL))) {
    rtwCAPI_SetChildMMI(*rt_ParentMMI, rt_ChildMMIIdx,
                        &(MotMapped_M->DataMapInfo.mmi));
    rtwCAPI_SetPath(MotMapped_M->DataMapInfo.mmi, rt_ChildPath);
    rtwCAPI_MMISetContStateStartIndex(MotMapped_M->DataMapInfo.mmi, rt_CSTATEIdx);
  }
}
